// CodeMirror Gherkin Mode with complete SpecFlow & Cucumber support
(function (mod) {
    if (typeof exports == "object" && typeof module == "object")
        mod(require("../../lib/codemirror"));
    else if (typeof define == "function" && define.amd)
        define(["../../lib/codemirror"], mod);
    else
        mod(CodeMirror);
})(function (CodeMirror) {
    "use strict";

    CodeMirror.defineMode("gherkin", function () {
        return {
            startState: function () {
                return { inDocstring: false, atLineStart: true };
            },
            token: function (stream, state) {
                if (stream.sol()) {
                    state.atLineStart = true;
                }

                // Handle multiline docstrings """
                if (state.inDocstring) {
                    if (stream.match('"""')) {
                        state.inDocstring = false;
                        return "string";
                    }
                    stream.next();
                    return "string";
                }

                if (stream.eatSpace()) {
                    return null;
                }

                // Docstrings """
                if (stream.match('"""')) {
                    state.inDocstring = true;
                    state.atLineStart = false;
                    return "string";
                }

                // Comments (# ...)
                if (stream.match(/#.*/)) {
                    return "comment";
                }

                // Tags (@smoke, @wip, @regression, etc.)
                if (stream.match(/@[A-Za-z0-9_-]+/)) {
                    return "tag";
                }

                // Section and Step keywords are ONLY valid at the beginning of the line
                if (state.atLineStart) {
                    var secMatch = stream.match(/^(Feature|Ability|Business Need|Scenario Outline|Scenario Template|Scenario|Background|Examples|Rule):?/i);
                    if (secMatch) {
                        state.atLineStart = false;
                        return "keyword";
                    }

                    var stepMatch = stream.match(/^(Given|When|Then|And|But|\*)\b/);
                    if (stepMatch) {
                        state.atLineStart = false;
                        return "def";
                    }
                }

                state.atLineStart = false;

                // Double or single quoted string literals
                if (stream.match(/"([^"\\]|\\.)*"/)) {
                    return "string";
                }
                if (stream.match(/'([^'\\]|\\.)*'/)) {
                    return "string";
                }

                // Scenario Outline placeholders: <param_name>
                if (stream.match(/<[^>\s]+>/)) {
                    return "variable";
                }

                // Data table delimiters
                if (stream.match(/\|/)) {
                    return "bracket";
                }

                // Standalone numeric values
                if (stream.match(/^\b\d+(\.\d+)?\b/)) {
                    return "number";
                }

                // Plain words (avoid matching numbers or keywords within words)
                if (stream.match(/^[a-zA-Z_]\w*/)) {
                    return null;
                }

                // Single characters
                stream.next();
                return null;
            }
        };
    });

    CodeMirror.defineMIME("text/x-gherkin", "gherkin");
    CodeMirror.defineMIME("text/x-feature", "gherkin");
});